INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Abschlussprüfung immer gesetzlich vorgeschrieben?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Unternehmensgröße"}, {"text": "Ja", "correct": false, "because": "Nicht für alle Firmen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was überprüfe ich bei einer Abschlussprüfung?', 3, '[{"text": "Richtigkeit der Daten", "correct": true, "because": "Sicherstellung der Genauigkeit"}, {"text": "Zukünftige Prognosen", "correct": false, "because": "Nicht primär"}, {"text": "Mitarbeiterleistung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Abschlussprüfung?', 5, '[{"text": "Bilanzprüfung", "correct": true, "because": "Finanzielle Richtigkeit"}, {"text": "Berichterstattung", "correct": true, "because": "Dokumentiert Ergebnisse"}, {"text": "Marketingplan", "correct": false, "because": "Kein Prüfungsbestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Abschlussprüfung dient der Transparenz. b) Sie ist nur für Projekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch für Finanzen, nicht nur Projekte"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer Abschlussprüfung?', 4, '[{"text": "Rechnungslegungsvorschriften", "correct": false, "because": "Grundlage der Prüfung"}, {"text": "Dokumentation", "correct": false, "because": "Wichtig für Nachweis"}, {"text": "Firmenfarben", "correct": true, "because": "Irrelevant für Prüfung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Abschlussprüfung freiwillig sein kann?', 2, '[{"text": "Ja", "correct": true, "because": "Bei kleinen Firmen möglich"}, {"text": "Nein", "correct": false, "because": "Nicht immer Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer führt eine Abschlussprüfung typischerweise durch?', 3, '[{"text": "Wirtschaftsprüfer", "correct": true, "because": "Unabhängige Prüfung"}, {"text": "Projektmanager", "correct": false, "because": "Eher interne Rolle"}, {"text": "Kunden", "correct": false, "because": "Nicht üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Abschlussprüfung eines Projekts?', 5, '[{"text": "Erfüllung der Ziele", "correct": true, "because": "Prüft Projekterfolg"}, {"text": "Abschlussbericht", "correct": true, "because": "Dokumentiert Ergebnisse"}, {"text": "Zukunftsplanung", "correct": false, "because": "Nicht Teil der Prüfung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Abschlussprüfung ist teuer. b) Sie ist nur für Großunternehmen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch für kleine Firmen möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Abschlussprüfung unwichtig?', 4, '[{"text": "Gesetzliche Vorgaben", "correct": false, "because": "Müssen eingehalten werden"}, {"text": "Prüfungsstandards", "correct": false, "because": "Grundlage der Arbeit"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein Prüfungskriterium"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Abschlussprüfung nur finanziell?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Projekte umfassend"}, {"text": "Ja", "correct": false, "because": "Nicht nur Bilanzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt eine Abschlussprüfung?', 4, '[{"text": "Vertrauen der Stakeholder", "correct": true, "because": "Bestätigt Richtigkeit"}, {"text": "Rechtssicherheit", "correct": true, "because": "Erfüllt Vorschriften"}, {"text": "Schnellere Prozesse", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Abschlussprüfungen immer extern sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch intern sein"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend extern"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Abschlussprüfung?', 3, '[{"text": "Genauigkeit", "correct": true, "because": "Kern der Prüfung"}, {"text": "Schnelligkeit", "correct": false, "because": "Qualität zählt"}, {"text": "Kosteneinsparung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Abschlussprüfung schließt Haftungsrisiken aus. b) Sie überprüft die Vergangenheit.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Haftung nicht ausgeschlossen"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine Abschlussprüfung?', 5, '[{"text": "Hoher Aufwand", "correct": true, "because": "Zeit- und kostenintensiv"}, {"text": "Komplexität", "correct": true, "because": "Erfordert Expertise"}, {"text": "Schnelle Ergebnisse", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Abschlussprüfung sekundär?', 3, '[{"text": "Prüfungsdokumentation", "correct": false, "because": "Wichtig für Nachweis"}, {"text": "Einhaltung von Normen", "correct": false, "because": "Pflicht"}, {"text": "Prüferanzahl", "correct": true, "because": "Nicht entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Dient die Abschlussprüfung der Steuerprüfung?', 3, '[{"text": "Nein", "correct": true, "because": "Unabhängiges Ziel"}, {"text": "Ja", "correct": false, "because": "Eigenständige Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Abschlussprüfung Fehler übersehen darf?', 2, '[{"text": "Nein", "correct": true, "because": "Ziel ist Fehlerfreiheit"}, {"text": "Ja", "correct": false, "because": "Prüfung soll vollständig sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Abschlussprüfung bei Projekten?', 4, '[{"text": "Bestätigung des Erfolgs", "correct": true, "because": "Prüft Zielerreichung"}, {"text": "Planung der nächsten Phase", "correct": false, "because": "Nicht Aufgabe"}, {"text": "Teambeurteilung", "correct": false, "because": "Nicht Fokus"}]');
